pub fn check_core_a_kept_lambda<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, want: &Ty, value: &Expr, span: &Span) {
    let inner: Ty = match want {
        Ty::Nullable(held) => { let held = nikaia_std::boxed::open(held); held.clone() },
        _ => want.clone(),
    };
    match inner {
        Ty::Named { ref name, ref args, .. } => {
            if name == "Vec" || name == "List" || name == ARRAY {
                match value {
                    Expr::ListLit { items, .. } => {
                        if !args.is_empty() {
                            for item in items.iter() { check_core_a_kept_lambda(state, world, host, nikaia_std::index::get(&args, 0), item, span); }
                            return;
                        }
                    },
                    _ => { },
                }
            }
        },
        Ty::Fn { ref params, ref result, is_sync, can_throw } => {
            let result = nikaia_std::boxed::open(result);
            match value {
                Expr::Closure { .. } => {
                    state.facts.kept_lambdas.insert(id_of(value) as i64, (!is_sync, can_throw));
                    state.a_kept_lambdas_result(id_of(value) as i64, (result).as_ref(), !is_sync, can_throw);
                    state.a_lambdas_text_is_its_own(world, &inner, value);
                    state.a_kept_lambdas_hulls(world, value);
                    state.a_kept_lambda_takes_these(world, value, !is_sync, "a function kept for later", span);
                },
                Expr::Variable(name, _) => {
                    let name = *name;
                    let named = world.words.resolve(name).to_string();
                    if state.lookup(&named).is_none() && world.own.functions.contains_key(&named) {
                        check_core_a_kept_function(state, world, host, params, is_sync, can_throw, false, value, span);
                        return;
                    }
                    let local = match state.binding(&named) { Some(__nikaia_value) => __nikaia_value, None => return };
                    let closure: Expr = match state.facts.let_lambdas.get(&local.id) { Some(__nikaia_value) => __nikaia_value, None => return }.clone();
                    if !state.facts.kept_lambdas.contains_key(&node_key(&closure)) {
                        check_core_a_kept_lambda(state, world, host, want, &closure, span);
                        state.facts.let_kept_lambdas.insert(node_key(&closure));
                        if !state.facts.lambda_params_by_use.contains_key(&node_key(&closure)) { state.facts.lambda_params_by_use.insert(node_key(&closure), params.to_owned()); }
                    }
                    let was_run = state.run_code.remove(&named);
                },
                Expr::Path(segments, _) => {
                    let mut names: Vec<String> = vec![];
                    for segment in segments.iter() {
                        let segment = *segment;
                        names.push(world.words.resolve(segment).to_string());
                    }
                    let joined = names.join("::");
                    if world.own.functions.contains_key(&joined) {
                        let contract = match ledger_function(world, &joined) { Some(__nikaia_value) => __nikaia_value, None => return };
                        let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return };
                        check_core_a_kept_function(state, world, host, params, is_sync, can_throw, signature.takes_a_receiver(), value, span);
                    }
                },
                _ => { },
            }
        },
        _ => { },
    }
}

